code='''def transform(grid):
    n, w = len(grid), len(grid[0])
    # Full horizontal bands encode a repeating sequence of row colors.
    bands = True
    row_values = []
    for row in grid:
        nz = {v for v in row if v}
        if len(nz) > 1:
            bands = False
            break
        row_values.append(next(iter(nz)) if nz else 0)
    if bands:
        period = 1
        while True:
            vals = {}
            ok = True
            for r, v in enumerate(row_values):
                if v:
                    k = r % period
                    if k in vals and vals[k] != v:
                        ok = False
                        break
                    vals[k] = v
            if ok:
                break
            period += 1
        fallback = next(iter(vals.values()))
        return [[row_values[r] or vals.get(r % period, fallback)] * w for r in range(n)]

    # Otherwise, colors repeat along diagonals of constant column minus row.
    period = 1
    while True:
        vals = {}
        ok = True
        for r, row in enumerate(grid):
            for c, v in enumerate(row):
                if v:
                    k = (c - r) % period
                    if k in vals and vals[k] != v:
                        ok = False
                        break
                    vals[k] = v
            if not ok:
                break
        if ok:
            break
        period += 1
    fallback = next(iter(vals.values()))
    return [[vals.get((c-r) % period, fallback) for c in range(w)] for r in range(n)]
